import { useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `./useDesignerLoopState` (app-internal store poll, unresolvable here) — a fixed sample
// active loop instead of a live poll. `bscRun` (`@/shared/lib/core/bsc`, a real CLI-invocation helper) is
// stubbed as a no-op. `./designerLoopBanner.css` is inlined below as real `style={{}}` values (the same
// declarations) since no stylesheet loads in this sandbox.
const SAMPLE_ACTIVE = { id: "loop-42", changes: 6, cost: 1.84 };
async function bscRun(..._args: unknown[]) {}

export function DesignerLoopBanner({ inline = false, active = SAMPLE_ACTIVE }: { inline?: boolean; active?: typeof SAMPLE_ACTIVE | null }) {
  const [starting, setStarting] = useState(false);
  const [stopRequested, setStopRequested] = useState(false);
  const overnight = null as null | { cursor: number; maxTurns: number; stopping?: boolean };

  const pillBase: React.CSSProperties = inline
    ? { display: "flex", alignItems: "center", gap: 8, flex: "0 0 auto" }
    : { display: "flex", alignItems: "center", gap: 9, padding: "5px 6px 5px 12px", borderRadius: 999, background: "var(--bg-elev)", border: "1px solid var(--border)", boxShadow: "0 6px 20px rgba(0, 0, 0, 0.28)", fontSize: 12 };

  const start = async () => {
    setStarting(true);
    try { await new Promise((r) => setTimeout(r, 300)); } finally { setStarting(false); }
  };

  if (!active) {
    return (
      <Box style={{ ...pillBase, padding: inline ? 0 : 4, background: inline ? "transparent" : "color-mix(in oklch, var(--bg-elev) 82%, transparent)", boxShadow: inline ? "none" : "0 4px 14px rgba(0, 0, 0, 0.18)", opacity: 0.72 }}>
        <Box
          as="button"
          type="button"
          onClick={() => void start()}
          disabled={starting}
          title="Start an autonomous, budget-bounded design run (bsc loop, overnight mode)"
          style={{ appearance: "none", cursor: "pointer", fontSize: 11, fontWeight: 600, padding: "3px 12px", borderRadius: 999, color: "var(--fg-muted)", background: "transparent", border: "1px solid var(--border)" }}
        >
          {starting ? "Starting…" : "Auto-improve"}
        </Box>
      </Box>
    );
  }

  const stop = () => {
    setStopRequested(true);
    void bscRun(null, ["loop", "stop", String(active.id)]);
  };

  const stopping = (overnight?.stopping ?? false) || stopRequested;

  return (
    <Box style={inline ? { ...pillBase, padding: "3px 4px 3px 10px", background: "var(--bg-elev)", borderColor: "var(--border)", border: "1px solid var(--border)" } : pillBase} role="status" aria-label="design loop running">
      <Box as="span" aria-hidden style={{ width: 8, height: 8, borderRadius: "50%", background: "var(--success)" }} />
      <Text as="span" mono weight={600} style={{ color: "var(--fg)" }}>
        design loop #{active.id}
      </Text>
      <Text as="span" mono style={{ color: "var(--fg-muted)" }}>
        {active.changes} change{active.changes === 1 ? "" : "s"} · ${active.cost.toFixed(2)}
        {overnight ? ` · auto ${overnight.cursor}/${overnight.maxTurns}` : ""}
      </Text>
      <Box
        as="button"
        type="button"
        onClick={stop}
        disabled={stopping}
        title="Halt the loop (bsc loop stop)"
        style={{ appearance: "none", cursor: "pointer", fontSize: 11, fontWeight: 600, padding: "3px 12px", borderRadius: 999, color: "#fff", background: "var(--danger, #d64545)", border: "1px solid transparent", opacity: stopping ? 0.7 : 1 }}
      >
        {stopping ? "Stopping…" : "Stop"}
      </Box>
    </Box>
  );
}
